const GUNS={pistol:{name:'Scrap pistol',mag:10,ammo:'rounds',damage:1.8,range:55,cooldown:.32,reload:1.6,spread:.018},shotgun:{name:'Pipe shotgun',mag:4,ammo:'shells',damage:.75,range:24,cooldown:.85,reload:2.5,spread:.09,pellets:7},rifle:{name:'Salvaged rifle',mag:20,ammo:'rounds',damage:1.3,range:80,cooldown:.13,reload:2.2,spread:.028,auto:true}};
